public class AccountService {

    // Locks on AccountService.class (Class object)
    public static synchronized void globalAudit() {
        // Only ONE thread can run ANY static synchronized method at a time
        // Lock: AccountService.class
    }

    // Locks on 'this' (specific instance)
    public synchronized void debit(BigDecimal amount) {
        // Only ONE thread per instance can run instance synchronized methods
        // Lock: this (the AccountService instance)
    }

    // THESE TWO CAN RUN SIMULTANEOUSLY!
    // Thread-1: AccountService.globalAudit()    → locks AccountService.class
    // Thread-2: instance.debit(amount)           → locks 'this'
    // Different locks → no blocking → parallel!

    // But:
    // Thread-1: instance.debit(amount)           → locks 'this'
    // Thread-2: instance.getBalance()            → locks 'this' (SAME lock!)
    // Same lock → Thread-2 BLOCKED!

    public synchronized BigDecimal getBalance() {
        return balance;  // locks on 'this' — same as debit()
    }

    // Equivalent explicit form:
    public static void globalAuditExplicit() {
        synchronized (AccountService.class) {  // Class lock
            // ...
        }
    }

    public void debitExplicit(BigDecimal amount) {
        synchronized (this) {  // Instance lock
            // ...
        }
    }
}

// ═══ LOCK COMBINATIONS ═══
// static sync + static sync (same class)  → SAME Class lock → BLOCKED
// instance sync + instance sync (same obj) → SAME this lock → BLOCKED
// instance sync + instance sync (diff obj) → DIFFERENT this → PARALLEL!
// static sync + instance sync             → DIFFERENT locks → PARALLEL!
