// ─── File: src/test/java/com/bank/locks/StaticVsInstanceSyncTest.java ───
package com.bank.locks;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class StaticVsInstanceSyncTest {

    static class AccountService {
        private int balance = 100000;

        // Locks on AccountService.class
        static synchronized void globalAudit(AtomicBoolean running, CountDownLatch started) {
            running.set(true);
            started.countDown();
            try { Thread.sleep(500); } catch (InterruptedException e) { }
            running.set(false);
        }

        // Locks on 'this'
        synchronized void debit(int amount) {
            balance -= amount;
        }

        synchronized int getBalance() { return balance; }
    }

    // ═══ PROOF: static sync and instance sync run in PARALLEL ═══
    @Test
    void staticAndInstance_runInParallel() throws InterruptedException {
        AccountService service = new AccountService();
        AtomicBoolean auditRunning = new AtomicBoolean(false);
        CountDownLatch auditStarted = new CountDownLatch(1);

        // Thread-1: static synchronized (Class lock)
        Thread auditThread = new Thread(() ->
            AccountService.globalAudit(auditRunning, auditStarted));
        auditThread.start();
        auditStarted.await();

        // Thread-2: instance synchronized (this lock) — should NOT be blocked!
        long start = System.currentTimeMillis();
        service.debit(1000);  // runs immediately! Different lock!
        long elapsed = System.currentTimeMillis() - start;

        assertThat(auditRunning.get()).isTrue();  // audit still running!
        assertThat(elapsed).isLessThan(100);       // debit wasn't blocked!
        assertThat(service.getBalance()).isEqualTo(99000);

        auditThread.join();
    }

    // ═══ PROOF: two instance syncs on SAME object → BLOCKED ═══
    @Test
    void twoInstanceSyncs_sameObject_blocked() throws InterruptedException {
        AccountService service = new AccountService();
        CountDownLatch debitStarted = new CountDownLatch(1);

        Thread slowDebit = new Thread(() -> {
            synchronized (service) {
                debitStarted.countDown();
                try { Thread.sleep(300); } catch (InterruptedException e) { }
                service.balance -= 1000;
            }
        });
        slowDebit.start();
        debitStarted.await();

        // getBalance locks on SAME 'this' → BLOCKED until slowDebit finishes
        long start = System.currentTimeMillis();
        int balance = service.getBalance();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isGreaterThanOrEqualTo(200);  // was blocked!
        slowDebit.join();
    }

    // ═══ PROOF: two instance syncs on DIFFERENT objects → PARALLEL ═══
    @Test
    void twoInstanceSyncs_differentObjects_parallel() throws InterruptedException {
        AccountService rajesh = new AccountService();
        AccountService priya = new AccountService();
        CountDownLatch latch = new CountDownLatch(2);

        long start = System.currentTimeMillis();

        new Thread(() -> {
            synchronized (rajesh) {
                try { Thread.sleep(200); } catch (InterruptedException e) { }
                rajesh.balance -= 1000;
            }
            latch.countDown();
        }).start();

        new Thread(() -> {
            synchronized (priya) {
                try { Thread.sleep(200); } catch (InterruptedException e) { }
                priya.balance -= 2000;
            }
            latch.countDown();
        }).start();

        latch.await();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(400);  // parallel! ~200ms, not ~400ms
        assertThat(rajesh.getBalance()).isEqualTo(99000);
        assertThat(priya.getBalance()).isEqualTo(98000);
    }
}
